#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>

DHT sensor(7, DHT11);
TM1637Display display(4, 3);
bool showHumidity = false;
bool haveReading = false;
float temperatureValue = 0;
float humidityValue = 0;
int lastRaw = HIGH;
int stableButton = HIGH;
unsigned long changedAt = 0;
unsigned long sampledAt = 0;
bool firstSample = true;

void refreshOutputs() {
  if (!haveReading) return;
  int duty = 0;
  if (temperatureValue > 30.0f) {
    duty = constrain((int)ceil((temperatureValue - 30.0f) * 255.0f / 20.0f), 1, 255);
  }
  analogWrite(5, duty);
  float value = showHumidity ? humidityValue : temperatureValue;
  display.showNumberDec((int)round(value), false);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(5, OUTPUT);
  analogWrite(5, 0);
  sensor.begin();
  display.setBrightness(7);
  display.clear();
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableButton && now - changedAt >= 40) {
    stableButton = raw;
    if (stableButton == LOW) {
      showHumidity = !showHumidity;
      refreshOutputs();
    }
  }
  if (firstSample || now - sampledAt >= 2000) {
    firstSample = false;
    sampledAt = now;
    float h = sensor.readHumidity();
    float t = sensor.readTemperature();
    if (!isnan(t) && !isnan(h)) {
      temperatureValue = t;
      humidityValue = h;
      haveReading = true;
      refreshOutputs();
    }
  }
}
